def forward(self, taskInfo):
    # 1. Chain‑of‑Thought agent that outputs a clean arithmetic expression
    cot_instruction = (
        "Please think step by step and solve the problem. "
        "When you reach the final numeric answer, output it **only** as a simple arithmetic expression "
        "(e.g., 3*4+5) in the field `expr`. Do not add any surrounding text or units."
    )
    cot_agent = LLMAgentBase(['thinking', 'expr'], 'CoT Calculator Agent', temperature=0.3)

    # 2. Run the agent on the task
    thinking, expr_info = cot_agent([taskInfo], cot_instruction)

    # 3. Extract the expression string
    expr = expr_info.content.strip()

    # 4. Safely evaluate the arithmetic expression
    # Allow only numbers and + - * / // ** and parentheses
    import ast, operator

    # Mapping of ast operator nodes to actual functions
    ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    def eval_node(node):
        if isinstance(node, ast.Num):  # <number>
            return node.n
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return ops[type(node.op)](left, right)
        if isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            return ops[type(node.op)](operand)
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        # Disallow any other constructs
        raise ValueError('Unsupported expression')

    try:
        parsed = ast.parse(expr, mode='eval')
        result = eval_node(parsed)
    except Exception as e:
        # Fallback: if evaluation fails, just return the raw expression
        result = expr

    # 5. Return the numeric result as a string (the framework accepts str)
    return str(result)
}
